--
-- Name: dbt_program_create_wizard; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dbt_program_create_wizard (
    id integer NOT NULL,
    base_event_id integer,
    "interval" integer,
    count integer,
    day integer,
    trigger_id integer,
    create_uid integer,
    write_uid integer,
    currency_id integer NOT NULL,
    company_id integer,
    cycle_duration integer NOT NULL,
    approver_group_id integer,
    max_individual_in_group integer,
    entitlement_validation_group_id integer,
    name character varying NOT NULL,
    event_tz character varying,
    rrule character varying,
    rrule_type character varying NOT NULL,
    end_type character varying,
    month_by character varying,
    weekday character varying,
    byday character varying,
    entitlement_kind character varying,
    target_type character varying,
    import_beneficiaries character varying,
    state character varying,
    until date,
    eligibility_domain text NOT NULL,
    amount_per_cycle numeric,
    amount_per_individual_in_group numeric,
    transfer_fee_pct numeric,
    transfer_fee_amt numeric,
    mon boolean,
    tue boolean,
    wed boolean,
    thu boolean,
    fri boolean,
    sat boolean,
    sun boolean,
    auto_approve_entitlements boolean,
    create_date timestamp without time zone,
    write_date timestamp without time zone,
    is_reimbursement_program boolean,
    portal_form_builder_id integer,
    is_multiple_form_submission boolean,
    CONSTRAINT dbt_program_create_wizard_month_day CHECK ((((rrule_type)::text <> 'monthly'::text) OR ((month_by)::text <> 'day'::text) OR ((day >= 1) AND (day <= 31)) OR (((weekday)::text = ANY ((ARRAY['MON'::character varying, 'TUE'::character varying, 'WED'::character varying, 'THU'::character varying, 'FRI'::character varying, 'SAT'::character varying, 'SUN'::character varying])::text[])) AND ((byday)::text = ANY ((ARRAY['1'::character varying, '2'::character varying, '3'::character varying, '4'::character varying, '-1'::character varying])::text[])))))
);


