--
-- Name: dbt_program_fund_report_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dbt_program_fund_report_view AS
 WITH trans AS (
         SELECT a1.name,
            NULL::integer AS partner_id,
            a1.company_id,
            a1.program_id,
            NULL::integer AS cycle_id,
            a1.journal_id,
            a1.date_posted,
            a1.amount,
            a1.currency_id
           FROM public.dbt_program_fund a1
          WHERE ((a1.state)::text = 'posted'::text)
        UNION ALL
         SELECT b1.code AS name,
            b1.partner_id,
            b1.company_id,
            b3.id AS program_id,
            b2.id AS cycle_id,
            b1.journal_id,
            b5.date AS date_posted,
            (b4.amount * ('-1'::integer)::numeric) AS amount,
            b4.currency_id
           FROM ((((public.dbt_entitlement b1
             LEFT JOIN public.dbt_cycle b2 ON ((b2.id = b1.cycle_id)))
             LEFT JOIN public.dbt_program b3 ON ((b3.id = b2.program_id)))
             LEFT JOIN public.account_payment b4 ON ((b4.id = b1.disbursement_id)))
             LEFT JOIN public.account_move b5 ON ((b5.id = b4.move_id)))
          WHERE ((b1.disbursement_id IS NOT NULL) AND ((b4.payment_type)::text = 'outbound'::text))
        )
 SELECT row_number() OVER (ORDER BY date_posted) AS id,
    name,
    partner_id,
    company_id,
    program_id,
    cycle_id,
    journal_id,
    date_posted,
    amount,
    currency_id
   FROM trans
  ORDER BY date_posted;


